    nearbyFood: { bn: 'পাটগ্রাম ও দহগ্রাম বাজারে সাধারণ ভাতের হোটেল ও চায়ের দোকান আছে।', en: 'Patgram and Dahagram bazaars have simple rice hotels and tea stalls.' },
    facilities: [],
